#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int R, C;
char rows[10][11];
int len[10];
int dp[10][1<<10]; // dp[row][mask] = max points up to this row with given placement mask
int scoreRow[10][1<<10]; // score within row for given mask
int scoreVert[10][1<<10][1<<10]; // vertical score between two masks

void precompute() {
    int masks = 1 << C;
    for (int r = 0; r < R; r++) {
        for (int m = 0; m < masks; m++) {
            int pos = 0;
            int ok = 1;
            int hor = 0;
            char line[11];
            for (int c = 0; c < C; c++) line[c] = ' ';
            for (int c = 0; c < C; c++) {
                if ((m >> c) & 1) {
                    if (pos >= len[r]) { ok = 0; break; }
                    line[c] = rows[r][pos++];
                }
            }
            if (pos != len[r]) ok = 0;
            if (!ok) {
                scoreRow[r][m] = -1;
                continue;
            }
            for (int c = 0; c < C - 1; c++) {
                if (line[c] != ' ' && line[c+1] != ' ' && line[c] == line[c+1])
                    hor++;
            }
            scoreRow[r][m] = hor;
        }
    }
    for (int r = 1; r < R; r++) {
        for (int m1 = 0; m1 < masks; m1++) {
            if (scoreRow[r-1][m1] < 0) continue;
            for (int m2 = 0; m2 < masks; m2++) {
                if (scoreRow[r][m2] < 0) continue;
                int ver = 0;
                int pos1 = 0, pos2 = 0;
                for (int c = 0; c < C; c++) {
                    char ch1 = ' ', ch2 = ' ';
                    if ((m1 >> c) & 1) ch1 = rows[r-1][pos1++];
                    if ((m2 >> c) & 1) ch2 = rows[r][pos2++];
                    if (ch1 != ' ' && ch2 != ' ' && ch1 == ch2) ver++;
                }
                scoreVert[r][m1][m2] = ver;
            }
        }
    }
}

int main() {
    scanf("%d %d", &R, &C);
    for (int i = 0; i < R; i++) {
        scanf("%s", rows[i]);
        len[i] = strlen(rows[i]);
    }
    precompute();
    int masks = 1 << C;
    for (int m = 0; m < masks; m++) {
        if (scoreRow[0][m] >= 0)
            dp[0][m] = scoreRow[0][m];
        else
            dp[0][m] = -1;
    }
    for (int r = 1; r < R; r++) {
        for (int m2 = 0; m2 < masks; m2++) {
            if (scoreRow[r][m2] < 0) { dp[r][m2] = -1; continue; }
            int best = -1;
            for (int m1 = 0; m1 < masks; m1++) {
                if (dp[r-1][m1] < 0) continue;
                int val = dp[r-1][m1] + scoreRow[r][m2] + scoreVert[r][m1][m2];
                if (val > best) best = val;
            }
            dp[r][m2] = best;
        }
    }
    int ans = 0;
    for (int m = 0; m < masks; m++) {
        if (dp[R-1][m] > ans) ans = dp[R-1][m];
    }
    printf("%d\n", ans);
    return 0;
}

