int main() {
    scanf("%d %d", &R, &C);
    for (int i = 0; i < R; i++) scanf("%s", s[i]);

    // Compute horizontal points for each row
    int hpts[MAXR] = {0};
    for (int i = 0; i < R; i++)
        for (int j = 0; s[i][j+1]; j++)
            if (s[i][j] == s[i][j+1]) hpts[i]++;

    int L[MAXR];
    for (int i = 0; i < R; i++) L[i] = strlen(s[i]);

    int total_hpts = 0;
    for (int i = 0; i < R; i++) total_hpts += hpts[i];

    for (int p = 0; p + L[0] <= C; p++) dp[0][p] = 0;

    for (int i = 0; i + 1 < R; i++) {
        for (int q = 0; q + L[i+1] <= C; q++) {
            int best = -1;
            for (int p = 0; p + L[i] <= C; p++) {
                if (dp[i][p] < 0 && i > 0) continue;
                int d = q - p;
                int cnt = 0;
                for (int j = 0; j < L[i]; j++) {
                    int k = j - d;
                    if (k >= 0 && k < L[i+1] && s[i][j] == s[i+1][k]) cnt++;
                }
                if (dp[i][p] + cnt > best) best = dp[i][p] + cnt;
            }
            dp[i+1][q] = best;
        }
    }

    int ans = 0;
    for (int p = 0; p + L[R-1] <= C; p++) if (dp[R-1][p] > ans) ans = dp[R-1][p];

    printf("%d\n", total_hpts * 2 + ans * 2);
    return 0;
