#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXR 105
#define MAXC 105
#define INF_NEG (-1000000000)

static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;

    static char s[MAXR][MAXC];
    static int len[MAXR];
    for (int i = 0; i < R; i++) {
        scanf("%s", s[i]);
        len[i] = (int)strlen(s[i]);
    }

    /*
      Let row i string of length Li be placed starting at column p (0-based),
      where 0 <= p <= C-Li.

      Score consists of:
      1) Horizontal equal-adjacent pairs inside each row, counted twice in total
         (once for each endpoint). This is independent of placement.
      2) Vertical equal-adjacent pairs between consecutive rows, also counted twice.

      So:
      total = const_horizontal + 2 * sum over adjacent rows of
              (# overlapping columns where characters are equal)

      DP over rows:
      dp[i][p] = maximum vertical contribution (already multiplied by 2)
                 up to row i, if row i starts at p.
    */

    int horizontal = 0;
    for (int i = 0; i < R; i++) {
        for (int j = 0; j + 1 < len[i]; j++) {
            if (s[i][j] == s[i][j + 1]) horizontal += 2;
        }
    }

    static int dp_prev[MAXC], dp_cur[MAXC];

    int ways0 = C - len[0] + 1;
    for (int p = 0; p < ways0; p++) dp_prev[p] = 0;

    for (int i = 1; i < R; i++) {
        int prevWays = C - len[i - 1] + 1;
        int curWays = C - len[i] + 1;

        for (int p = 0; p < curWays; p++) dp_cur[p] = INF_NEG;

        for (int p1 = 0; p1 < prevWays; p1++) {
            for (int p2 = 0; p2 < curWays; p2++) {
                int L = p1 > p2 ? p1 : p2;
                int Rr = (p1 + len[i - 1] < p2 + len[i]) ? (p1 + len[i - 1]) : (p2 + len[i]);
                int add = 0;
                for (int col = L; col < Rr; col++) {
                    if (s[i - 1][col - p1] == s[i][col - p2]) add += 2;
                }
                dp_cur[p2] = max(dp_cur[p2], dp_prev[p1] + add);
            }
        }

        for (int p = 0; p < curWays; p++) dp_prev[p] = dp_cur[p];
    }

    int ans = horizontal;
    if (R == 1) {
        printf("%d\n", ans);
        return 0;
    }

    int lastWays = C - len[R - 1] + 1;
    int best = 0;
    for (int p = 0; p < lastWays; p++) best = max(best, dp_prev[p]);

    ans += best;
    printf("%d\n", ans);
    return 0;
}

