public class Connect {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt();
        int C = sc.nextInt();
        sc.nextLine();
        String[] strings = new String[R];
        for (int i = 0; i < R; i++) {
            strings[i] = sc.nextLine().trim();
        }

        // Precompute horizontal score for each row for each start position
        int[][] horScore = new int[R][C];
        for (int r = 0; r < R; r++) {
            String s = strings[r];
            int len = s.length();
            for (int start = 0; start <= C - len; start++) {
                int score = 0;
                for (int j = 0; j < len; j++) {
                    if (j > 0 && s.charAt(j) == s.charAt(j - 1)) score++;
                }
                horScore[r][start] = score;
            }
        }

        // DP: dp[r][start] = max score up to row r with row r starting at 'start'
        int[][] dp = new int[R][C];
        for (int[] row : dp) Arrays.fill(row, Integer.MIN_VALUE);

        // Initialize first row
        int len0 = strings[0].length();
        for (int start = 0; start <= C - len0; start++) {
            dp[0][start] = horScore[0][start];
        }

        // Fill DP
        for (int r = 1; r < R; r++) {
            String prevStr = strings[r - 1];
            String curStr = strings[r];
            int prevLen = prevStr.length();
            int curLen = curStr.length();

            for (int curStart = 0; curStart <= C - curLen; curStart++) {
                int bestPrev = Integer.MIN_VALUE;
                for (int prevStart = 0; prevStart <= C - prevLen; prevStart++) {
                    if (dp[r - 1][prevStart] == Integer.MIN_VALUE) continue;
                    int verticalScore = 0;
                    int maxCol = Math.min(prevLen, curLen);
                    for (int k = 0; k < maxCol; k++) {
                        int prevCol = prevStart + k;
                        int curCol = curStart + k;
                        if (prevCol < C && curCol < C) {
                            if (prevStr.charAt(k) == curStr.charAt(k)) {
                                verticalScore++;
                            }
                        }
                    }
                    int total = dp[r - 1][prevStart] + horScore[r][curStart] + verticalScore;
                    bestPrev = Math.max(bestPrev, total);
                }
                dp[r][curStart] = bestPrev;
            }
        }

        int answer = Integer.MIN_VALUE;
        int lastLen = strings[R - 1].length();
        for (int start = 0; start <= C - lastLen; start++) {
            answer = Math.max(answer, dp[R - 1][start]);
        }
        System.out.println(answer);
    }
}

