public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt(), C = sc.nextInt();
        String[] s = new String[R];
        for (int i = 0; i < R; i++) s[i] = sc.next();

        int horizPoints = 0;
        for (int i = 0; i < R; i++)
            for (int j = 0; j+1 < s[i].length(); j++)
                if (s[i].charAt(j) == s[i].charAt(j+1)) horizPoints += 2;

        int[] dp = new int[C];
        int L0 = s[0].length();
        for (int a = 0; a <= C - L0; a++) dp[a] = 0;
        Arrays.fill(dp, Integer.MIN_VALUE / 2);
        for (int a = 0; a <= C - L0; a++) dp[a] = 0;

        for (int i = 1; i < R; i++) {
            int[] ndp = new int[C];
            Arrays.fill(ndp, Integer.MIN_VALUE / 2);
            int L1 = s[i-1].length(), L2 = s[i].length();
            for (int b = 0; b <= C - L2; b++) {
                for (int a = 0; a <= C - L1; a++) {
                    if (dp[a] == Integer.MIN_VALUE / 2) continue;
                    int score = 0;
                    int start = Math.max(a, b), end = Math.min(a+L1, b+L2);
                    for (int col = start; col < end; col++)
                        if (s[i-1].charAt(col-a) == s[i].charAt(col-b)) score += 2;
                    ndp[b] = Math.max(ndp[b], dp[a] + score);
                }
            }
            dp = ndp;
        }
        int best = 0;
        for (int v : dp) if (v != Integer.MIN_VALUE/2) best = Math.max(best, v);
        System.out.println(horizPoints + best);
    }
}

