public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int R = fs.nextInt();
        int C = fs.nextInt();
        String[] s = new String[R];
        int[] len = new int[R];
        for (int i = 0; i < R; i++) {
            s[i] = fs.next();
            len[i] = s[i].length();
        }

        // Horizontal contribution is fixed:
        // each equal adjacent pair contributes 2 points total.
        long base = 0;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j + 1 < len[i]; j++) {
                if (s[i].charAt(j) == s[i].charAt(j + 1)) base += 2;
            }
        }

        // DP over rows.
        // State for row i: starting column offset of s[i] in [0, C-len[i]]
        // dpPrev[a] = best vertical contribution up to previous row with that offset.
        long[] dpPrev = null;

        for (int i = 0; i < R; i++) {
            int maxStart = C - len[i];
            long[] dpCur = new long[maxStart + 1];

            if (i == 0) {
                Arrays.fill(dpCur, 0L);
            } else {
                int prevMaxStart = C - len[i - 1];
                char[] a = s[i - 1].toCharArray();
                char[] b = s[i].toCharArray();
                int L1 = len[i - 1], L2 = len[i];

                // For every pair of offsets (p, q), add 2 * overlapMatches(p, q)
                // overlapMatches depends only on d = q - p.
                // Since C <= manageable in intended constraints, O(states^2 * overlap) is acceptable.
                Arrays.fill(dpCur, Long.MIN_VALUE / 4);

                for (int p = 0; p <= prevMaxStart; p++) {
                    long prevVal = dpPrev[p];
                    for (int q = 0; q <= maxStart; q++) {
                        int left = Math.max(p, q);
                        int right = Math.min(p + L1 - 1, q + L2 - 1);
                        long add = 0;
                        if (left <= right) {
                            int startA = left - p;
                            int startB = left - q;
                            int cnt = right - left + 1;
                            for (int k = 0; k < cnt; k++) {
                                if (a[startA + k] == b[startB + k]) add += 2;
                            }
                        }
                        long cand = prevVal + add;
                        if (cand > dpCur[q]) dpCur[q] = cand;
                    }
                }
            }

            dpPrev = dpCur;
        }

        long bestVertical = 0;
        for (long v : dpPrev) bestVertical = Math.max(bestVertical, v);

        System.out.println(base + bestVertical);
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C;
    cin >> R >> C;
    vector<string> s(R);
    for (int i = 0; i < R; i++) {
        cin >> s[i];
    }

    // Precompute for each row: valid masks and internal scores
    vector<vector<int>> validMasks(R);
    vector<vector<int>> internalScore(R);

    for (int i = 0; i < R; i++) {
        int L = s[i].size();
        // Iterate all masks with exactly L bits set
        for (int mask = 0; mask < (1 << C); mask++) {
            if (__builtin_popcount(mask) != L) continue;
            // Check if we can place the string in order
            bool ok = true;
            int pos = 0;
            for (int col = 0; col < C; col++) {
                if (mask & (1 << col)) {
                    if (pos >= L) { ok = false; break; }
                    pos++;
                }
            }
            if (!ok) continue;

            // Build placement
            vector<char> rowChars(C, 0);
            pos = 0;
            for (int col = 0; col < C; col++) {
                if (mask & (1 << col)) {
                    rowChars[col] = s[i][pos++];
                }
            }

            // Internal horizontal score
            int score = 0;
            for (int col = 0; col < C - 1; col++) {
                if (rowChars[col] && rowChars[col+1] && rowChars[col] == rowChars[col+1]) {
                    score++;
                }
            }
            validMasks[i].push_back(mask);
            internalScore[i].push_back(score);
        }
    }

    // DP
    vector<vector<int>> dp(R);
    for (int i = 0; i < R; i++) {
        dp[i].assign(validMasks[i].size(), -1e9);
    }

    // Initialize first row
    for (int j = 0; j < (int)validMasks[0].size(); j++) {
        dp[0][j] = internalScore[0][j];
    }

    // Fill DP
    for (int i = 1; i < R; i++) {
        for (int j = 0; j < (int)validMasks[i].size(); j++) {
            int maskCurr = validMasks[i][j];
            // Build row chars for current mask
            vector<char> currRow(C, 0);
            int pos = 0;
            for (int col = 0; col < C; col++) {
                if (maskCurr & (1 << col)) {
                    currRow[col] = s[i][pos++];
                }
            }

            for (int k = 0; k < (int)validMasks[i-1].size(); k++) {
                int maskPrev = validMasks[i-1][k];
                // Build row chars for previous mask
                vector<char> prevRow(C, 0);
                pos = 0;
                for (int col = 0; col < C; col++) {
                    if (maskPrev & (1 << col)) {
                        prevRow[col] = s[i-1][pos++];
                    }
                }

                // Vertical score
                int vertScore = 0;
                for (int col = 0; col < C; col++) {
                    if (prevRow[col] && currRow[col] && prevRow[col] == currRow[col]) {
                        vertScore++;
                    }
                }

                dp[i][j] = max(dp[i][j], dp[i-1][k] + vertScore + internalScore[i][j]);
            }
        }
    }

    int ans = 0;
    for (int j = 0; j < (int)dp[R-1].size(); j++) {
        ans = max(ans, dp[R-1][j]);
    }
    cout << ans << '\n';

    return 0;
}

