int main() {
    int R, C;
    cin >> R >> C;
    vector<string> s(R);
    for (int i = 0; i < R; i++) cin >> s[i];

    // Horizontal score for each row (fixed)
    int horiz = 0;
    for (int i = 0; i < R; i++)
        for (int j = 0; j+1 < (int)s[i].size(); j++)
            if (s[i][j] == s[i][j+1]) horiz += 2;

    // dp[c] = max vertical score when row i starts at column c
    int maxStart0 = C - (int)s[0].size();
    vector<int> dp(C, -1);
    for (int c = 0; c <= maxStart0; c++) dp[c] = 0;

    for (int i = 1; i < R; i++) {
        int maxStart = C - (int)s[i].size();
        vector<int> ndp(C, -1);
        for (int c2 = 0; c2 <= maxStart; c2++) {
            int prev_max = C - (int)s[i-1].size();
            for (int c1 = 0; c1 <= prev_max; c1++) {
                if (dp[c1] < 0) continue;
                // vertical score between row i-1 starting at c1, row i starting at c2
                int vscore = 0;
                for (int k = 0; k < (int)s[i-1].size(); k++) {
                    int col = c1 + k;
                    int k2 = col - c2;
                    if (k2 >= 0 && k2 < (int)s[i].size())
                        if (s[i-1][k] == s[i][k2]) vscore += 2;
                }
                ndp[c2] = max(ndp[c2], dp[c1] + vscore);
            }
        }
        dp = ndp;
    }

    int ans = horiz + *max_element(dp.begin(), dp.end());
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C;
    cin >> R >> C;
    vector<string> s(R);
    for (int i = 0; i < R; ++i) cin >> s[i];

    // dp_prev[a][b]:
    // after processing previous row,
    // a = chosen start position of previous row
    // b = chosen end position of previous row
    // value = maximum score so far
    //
    // For a row with length L, valid placements are intervals [st, st+L-1].
    // We only need previous row interval to compute vertical contribution
    // with current row.
    //
    // Horizontal contribution of a row is fixed: 2 * (#equal adjacent pairs inside row)
    // because each equal horizontal edge contributes 1 point to both cells.

    const long long NEG = -(1LL << 60);
    vector<vector<long long>> dp_prev(C, vector<long long>(C, NEG));
    vector<vector<long long>> dp_cur(C, vector<long long>(C, NEG));

    auto horizontal_score = [&](const string& t) -> long long {
        long long res = 0;
        for (int i = 0; i + 1 < (int)t.size(); ++i) {
            if (t[i] == t[i + 1]) res += 2;
        }
        return res;
    };

    // First row
    int L0 = (int)s[0].size();
    long long base0 = horizontal_score(s[0]);
    for (int st = 0; st + L0 <= C; ++st) {
        int en = st + L0 - 1;
        dp_prev[st][en] = base0;
    }

    // Process rows 2..R
    for (int r = 1; r < R; ++r) {
        for (int i = 0; i < C; ++i)
            fill(dp_cur[i].begin(), dp_cur[i].end(), NEG);

        int Lp = (int)s[r - 1].size();
        int Lc = (int)s[r].size();
        long long base = horizontal_score(s[r]);

        for (int pst = 0; pst + Lp <= C; ++pst) {
            int pen = pst + Lp - 1;
            long long prevVal = dp_prev[pst][pen];
            if (prevVal == NEG) continue;

            for (int cst = 0; cst + Lc <= C; ++cst) {
                int cen = cst + Lc - 1;

                long long add = base;

                int L = max(pst, cst);
                int Rr = min(pen, cen);
                if (L <= Rr) {
                    for (int col = L; col <= Rr; ++col) {
                        if (s[r - 1][col - pst] == s[r][col - cst]) {
                            add += 2; // vertical equal edge contributes to both cells
                        }
                    }
                }

                dp_cur[cst][cen] = max(dp_cur[cst][cen], prevVal + add);
            }
        }

        dp_prev.swap(dp_cur);
    }

    long long ans = 0;
    for (int i = 0; i < C; ++i)
        for (int j = 0; j < C; ++j)
            ans = max(ans, dp_prev[i][j]);

    cout << ans << '\n';
    return 0;
}
